import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { RotateCcw } from "lucide-react";

/**
 * Excretory (urinary) system viewer on real Visible Human Male reference organs: both kidneys (capsule, cortex,
 * columns, pyramids, papillae, hilum), both renal pelves and the bladder, merged and simplified into one model that is
 * embedded at the bottom of this file, so this is the only file you need. The model has no ureters, so they are drawn
 * as simple tubes from each renal pelvis to the bladder opening. Check labels against your textbook.
 * Credit: Visible Human Male reference organs from NIH 3D / Human Reference Atlas (check each entry for its license).
 */
type Def = { name: string; fn: string; color: string; shell?: boolean; kid?: boolean; inner?: boolean };
const DEFS: Record<string, Def> = {
  capsule: { name: "Renal capsule", fn: "Thin, tough layer that wraps each kidney and protects it.", color: "#b85c58", shell: true, kid: true },
  cortex: { name: "Renal cortex", fn: "Outer layer of the kidney, where blood is first filtered by the nephrons.", color: "#e0a99c", shell: true, kid: true },
  column: { name: "Renal columns", fn: "Parts of the cortex that dip between the pyramids and carry blood vessels.", color: "#d8a090", kid: true, inner: true },
  pyramid: { name: "Renal pyramids (medulla)", fn: "Cone-shaped tissue that collects urine from the nephrons and drains it towards the papillae.", color: "#b05a5a", kid: true, inner: true },
  papilla: { name: "Renal papillae", fn: "Tips of the pyramids, where urine drips into the minor calyces.", color: "#f0c070", kid: true, inner: true },
  hilum: { name: "Renal hilum", fn: "Notch on the inner edge where the renal artery and vein enter and the ureter leaves.", color: "#c98080", kid: true, inner: true },
  pelvis: { name: "Renal pelvis", fn: "Funnel that gathers urine from the calyces and passes it into the ureter.", color: "#f2e6c8", inner: true },
  ureter: { name: "Ureters", fn: "Muscular tubes that push urine from each kidney down to the bladder in waves (peristalsis).", color: "#f2e6c8" },
  bladder: { name: "Urinary bladder", fn: "Stretchy muscular sac that stores urine until it is passed.", color: "#e6a8a8", shell: true },
  trigone: { name: "Trigone", fn: "Smooth triangle on the bladder floor between the two ureter openings and the exit to the urethra.", color: "#d97b7b", inner: true },
  orifice: { name: "Ureteral openings", fn: "Where each ureter enters the bladder at an angle, which stops urine flowing back up.", color: "#8a3f3f", inner: true },
  neck: { name: "Bladder neck", fn: "Ring of smooth muscle at the bladder exit. It stays closed until you pass urine.", color: "#c45f5f", inner: true },
};
const idOf = (n: string) =>
  /capsule/.test(n) ? "capsule" : /hilum/.test(n) ? "hilum" : /renal_column/.test(n) ? "column" : /cortex/.test(n) ? "cortex" : /papilla/.test(n) ? "papilla" :
  /pyramid/.test(n) ? "pyramid" : /renal_pelvis/.test(n) ? "pelvis" : /trigone/.test(n) ? "trigone" : /orifice/.test(n) ? "orifice" : /neck/.test(n) ? "neck" : /fundus|bladder/.test(n) ? "bladder" : null;
const UL = [[1.58, 3.126, 0.1],  [1.63, 2.226, -0.0],  [1.7, -0.494, -0.05],  [0.786, -3.863, -0.147],  [0.436, -4.113, -0.097]];
const UR = [[-1.569, 2.41, 0.646],  [-1.619, 1.51, 0.546],  [-1.689, -0.758, 0.496],  [-1.326, -3.677, -0.186],  [-0.976, -3.927, -0.136]];
const KZ0 = -1.785;
const KZ1 = 0.921;

export default function ExcretoryModelViewer({ label, blurb, theme }: { label: string; blurb: string; theme: "dark" | "light" }) {
  const dark = theme === "dark";
  const holder = useRef<HTMLDivElement>(null);
  const tip = useRef<HTMLDivElement>(null);
  const mats = useRef<Record<string, THREE.MeshStandardMaterial>>({});
  const plane = useRef(new THREE.Plane(new THREE.Vector3(0, 0, -1), KZ1));
  const st = useRef({ flow: 0.6, xray: false, cutOn: false, hov: null as string | null, pin: null as string | null, fly: null as THREE.Vector3 | null, cam: null as THREE.PerspectiveCamera | null, controls: null as OrbitControls | null });
  const [pin, setPin] = useState<string | null>(null);
  const [xray, setXray] = useState(false);
  const [cutOn, setCutOn] = useState(false);
  const [cut, setCut] = useState(50);
  const [flow, setFlow] = useState(60);
  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    const el = holder.current;
    if (!el) return;
    const s = st.current;
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.localClippingEnabled = true;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    el.appendChild(renderer.domElement);
    const scene = new THREE.Scene();
    const cam = new THREE.PerspectiveCamera(35, 1, 0.1, 100);
    cam.position.set(0, 0.6, 24);
    s.cam = cam;
    const controls = new OrbitControls(cam, renderer.domElement);
    controls.enableDamping = true;
    controls.enablePan = false;
    controls.minDistance = 8;
    controls.maxDistance = 45;
    s.controls = controls;
    scene.add(new THREE.HemisphereLight(0xffffff, 0x556688, 1.6));
    const d1 = new THREE.DirectionalLight(0xffffff, 1.4);
    d1.position.set(6, 6, 8);
    scene.add(d1);
    const d2 = new THREE.DirectionalLight(0xffffff, 0.7);
    d2.position.set(-6, 2, -8);
    scene.add(d2);
    const group = new THREE.Group();
    scene.add(group);
    Object.entries(DEFS).forEach(([id, d]) => {
      mats.current[id] = new THREE.MeshStandardMaterial({ color: d.color, roughness: 0.5, metalness: 0.02, side: THREE.DoubleSide });
    });
    const meshes: THREE.Mesh[] = [];
    let disposed = false;
    const tubeCurves: THREE.CatmullRomCurve3[] = [];
    const raw = atob(MODEL_B64);
    const bytes = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
    new GLTFLoader().parse(
      bytes.buffer as ArrayBuffer,
      "",
      (g) => {
        if (disposed) return;
        g.scene.traverse((o) => {
          const m = o as THREE.Mesh;
          if (!m.isMesh) return;
          const id = idOf(m.name);
          if (!id) return;
          m.geometry.computeVertexNormals();
          m.material = mats.current[id];
          m.userData = { id, side: /_L(_|$)/.test(m.name) ? "L" : /_R(_|$)/.test(m.name) ? "R" : "" };
          meshes.push(m);
        });
        group.add(g.scene);
        [UL, UR].forEach((pts) => {
          const c = new THREE.CatmullRomCurve3(pts.map((p) => new THREE.Vector3(p[0], p[1], p[2])));
          tubeCurves.push(c);
          const t = new THREE.Mesh(new THREE.TubeGeometry(c, 60, 0.05, 8), mats.current.ureter);
          t.userData = { id: "ureter", side: pts === UL ? "L" : "R" };
          group.add(t);
          meshes.push(t);
        });
        setReady(true);
      },
      () => setFailed(true),
    );
    const N = 14;
    const pg = new THREE.BufferGeometry();
    pg.setAttribute("position", new THREE.BufferAttribute(new Float32Array(N * 2 * 3), 3));
    const pm = new THREE.PointsMaterial({ color: "#ffd84a", size: 0.16, sizeAttenuation: true });
    const drops = new THREE.Points(pg, pm);
    drops.frustumCulled = false;
    group.add(drops);
    const resize = () => {
      renderer.setSize(el.clientWidth, el.clientHeight);
      cam.aspect = el.clientWidth / Math.max(el.clientHeight, 1);
      cam.updateProjectionMatrix();
    };
    const ro = new ResizeObserver(resize);
    ro.observe(el);
    resize();
    const rc = new THREE.Raycaster();
    const mp = new THREE.Vector2();
    const onMove = (e: PointerEvent) => {
      const r = renderer.domElement.getBoundingClientRect();
      mp.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
      rc.setFromCamera(mp, cam);
      const targets = meshes.filter((m) => !(s.xray && DEFS[m.userData.id].shell));
      const h = rc.intersectObjects(targets, false).find((x) => !(s.cutOn && DEFS[x.object.userData.id].kid && x.point.z > plane.current.constant));
      s.hov = h ? (h.object.userData.id as string) : null;
      const t = tip.current;
      if (t) {
        if (h) {
          const d = DEFS[s.hov!];
          const sd = h.object.userData.side === "L" ? "Left " : h.object.userData.side === "R" ? "Right " : "";
          t.innerHTML = `<b>${sd}${d.name}</b><br/>${d.fn}`;
          t.style.display = "block";
          t.style.left = Math.min(e.clientX - r.left + 14, r.width - 250) + "px";
          t.style.top = e.clientY - r.top + 14 + "px";
        } else t.style.display = "none";
      }
      renderer.domElement.style.cursor = h ? "pointer" : "grab";
    };
    const onLeave = () => {
      s.hov = null;
      if (tip.current) tip.current.style.display = "none";
    };
    const onClick = () => setPin((p) => (s.hov ? (p === s.hov ? null : s.hov) : null));
    renderer.domElement.addEventListener("pointermove", onMove);
    renderer.domElement.addEventListener("pointerleave", onLeave);
    renderer.domElement.addEventListener("click", onClick);
    const t0 = performance.now();
    const v = new THREE.Vector3();
    const still = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let raf = 0;
    const loop = () => {
      raf = requestAnimationFrame(loop);
      const t = (performance.now() - t0) / 1000;
      if (s.fly) {
        cam.position.lerp(s.fly, 0.12);
        if (cam.position.distanceTo(s.fly) < 0.05) s.fly = null;
      }
      controls.update();
      const sel = s.hov || s.pin;
      Object.entries(mats.current).forEach(([id, m]) => {
        m.emissive.set(sel === id ? DEFS[id].color : "#000000");
        m.emissiveIntensity = 0.5;
      });
      drops.visible = s.flow > 0.02 && tubeCurves.length === 2;
      if (drops.visible) {
        const a = pg.attributes.position as THREE.BufferAttribute;
        tubeCurves.forEach((c, k) => {
          for (let i = 0; i < N; i++) {
            const u = (((still ? 0 : t) * 0.12 * (0.3 + s.flow) + i / N) % 1 + 1) % 1;
            c.getPoint(u, v);
            a.setXYZ(k * N + i, v.x, v.y, v.z);
          }
        });
        a.needsUpdate = true;
      }
      renderer.render(scene, cam);
    };
    loop();
    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      ro.disconnect();
      controls.dispose();
      renderer.domElement.removeEventListener("pointermove", onMove);
      renderer.domElement.removeEventListener("pointerleave", onLeave);
      renderer.domElement.removeEventListener("click", onClick);
      meshes.forEach((m) => m.geometry.dispose());
      pg.dispose();
      pm.dispose();
      Object.values(mats.current).forEach((m) => m.dispose());
      renderer.dispose();
      if (renderer.domElement.parentNode === el) el.removeChild(renderer.domElement);
    };
  }, []);

  useEffect(() => {
    st.current.pin = pin;
  }, [pin]);
  useEffect(() => {
    st.current.flow = flow / 100;
  }, [flow]);
  useEffect(() => {
    st.current.xray = xray;
    Object.entries(DEFS).forEach(([id, d]) => {
      const m = mats.current[id];
      if (!m || !d.shell) return;
      m.transparent = xray;
      m.opacity = xray ? 0.22 : 1;
      m.depthWrite = !xray;
      m.needsUpdate = true;
    });
  }, [xray, ready]);
  useEffect(() => {
    st.current.cutOn = cutOn;
    plane.current.constant = KZ1 - (cut / 100) * (KZ1 - KZ0);
    Object.entries(DEFS).forEach(([id, d]) => {
      const m = mats.current[id];
      if (!m || !d.kid) return;
      m.clippingPlanes = cutOn ? [plane.current] : [];
      m.needsUpdate = true;
    });
  }, [cutOn, cut, ready]);

  const side = (z: 1 | -1) => {
    const c = st.current.cam;
    if (!c) return;
    const d = c.position.length();
    st.current.fly = new THREE.Vector3(0, d * 0.03, z * d * 0.99);
  };
  const fit = () => {
    st.current.fly = new THREE.Vector3(0, 0.6, 24);
    st.current.controls?.target.set(0, 0, 0);
  };
  const pick = (id: string) => {
    const next = pin === id ? null : id;
    setPin(next);
    if (next && DEFS[next].inner && !xray && !cutOn) setXray(true);
  };
  const sel = pin ? DEFS[pin] : null;
  const edge = dark ? "border-white/10" : "border-black/10";
  const txt = dark ? "text-slate-100" : "text-slate-900";
  const sub = dark ? "text-slate-400" : "text-slate-600";
  const btn = (on: boolean) => `cursor-pointer rounded-lg border px-3 py-1.5 text-xs font-semibold transition-colors ${edge} ${on ? "bg-[#6f7cff] text-white" : `${txt} hover:bg-white/10`}`;

  return (
    <div className="lab-split">
      <div className="lab-stage-pane lab-glass p-2.5 sm:p-4">
        <div className="mb-2.5 flex items-center justify-between gap-2">
          <div className="min-w-0">
            <p className={`truncate text-sm font-bold ${txt}`}>{label}</p>
            <p className={`hidden text-[11px] sm:block ${sub}`}>{blurb}</p>
          </div>
          <button type="button" className={btn(false)} onClick={fit}>
            <RotateCcw className="mr-1 inline h-3 w-3" />
            Fit view
          </button>
        </div>
        <div className="relative h-[58vh] min-h-[340px] overflow-hidden rounded-xl border border-white/10 bg-[#08080a]">
          <div ref={holder} className="absolute inset-0" />
          {!ready && !failed && <div className="absolute inset-0 grid place-items-center text-sm text-slate-400">Loading urinary system model…</div>}
          {failed && <div className="absolute inset-0 grid place-items-center px-6 text-center text-sm text-slate-400">Could not load the urinary system model.</div>}
          <div ref={tip} style={{ display: "none" }} className="pointer-events-none absolute z-10 max-w-[240px] rounded-lg bg-black/90 px-2.5 py-1.5 text-[11px] leading-snug text-white" />
          <p className="pointer-events-none absolute bottom-2 right-3 text-[10px] text-slate-400">drag orbit · scroll zoom · hover or tap a part</p>
        </div>
      </div>
      <div className="lab-deck-pane lab-glass-deep space-y-3 p-3.5">
        <div className="flex flex-wrap gap-2">
          <button type="button" className={btn(false)} onClick={() => side(1)}>Front</button>
          <button type="button" className={btn(false)} onClick={() => side(-1)}>Back</button>
          <button type="button" className={btn(xray)} onClick={() => setXray(!xray)}>X-ray</button>
          <button type="button" className={btn(cutOn)} onClick={() => setCutOn(!cutOn)}>Cut kidneys open</button>
        </div>
        <label className={`flex items-center gap-2 text-xs ${sub}`}>
          Cut depth
          <input type="range" min={0} max={100} value={cut} disabled={!cutOn} className="flex-1" onChange={(e) => setCut(+e.target.value)} />
          <b className={txt}>{cutOn ? `${cut}%` : "off"}</b>
        </label>
        <label className={`flex items-center gap-2 text-xs ${sub}`}>
          Urine flow
          <input type="range" min={0} max={100} value={flow} className="flex-1" onChange={(e) => setFlow(+e.target.value)} />
          <b className={txt}>{flow}%</b>
        </label>
        <div className={`min-h-20 rounded-xl border ${edge} p-3 text-xs leading-relaxed ${txt}`}>
          {sel ? (<><b style={{ color: sel.color }}>{sel.name}</b><br />{sel.fn}</>) : <span className={sub}>Hover or select a part to see what it does.</span>}
        </div>
        <div className="flex flex-col gap-1">
          {Object.entries(DEFS).map(([id, d]) => (
            <button key={id} type="button" onClick={() => pick(id)} onMouseEnter={() => (st.current.hov = id)} onMouseLeave={() => (st.current.hov = null)}
              className={`flex cursor-pointer items-center gap-2 rounded-lg border px-2 py-1 text-left text-xs ${edge} ${txt} ${pin === id ? "bg-white/10" : ""}`}>
              <i className="h-2.5 w-2.5 flex-none rounded-full" style={{ background: d.color }} />
              {d.name}
            </button>
          ))}
        </div>
        <p className={`text-[10px] leading-relaxed ${sub}`}>Use X-ray or Cut kidneys open to see the layers inside. The ureters are drawn as simple tubes joining each renal pelvis to the bladder, and the yellow dots show urine moving down them. Model: Visible Human Male reference organs (NIH 3D / Human Reference Atlas).</p>
      </div>
    </div>
  );
}

// Embedded model data (about 2 MB). Do not edit by hand.
// prettier-ignore
const MODEL_B64 =
  "";
